<?php
require_once __DIR__ . '/../_common.php';api_require_role('fo');
try{$m=api_allow_methods(['GET','POST']);$id=(int)$_SESSION['id_akun'];if($m==='GET'){$s=$conn->prepare("SELECT id_akun,nama,email,no_telp,tanggal_lahir,gender,alamat,photo_profile,hari_kerja_mulai,hari_kerja_selesai,jam_mulai,jam_selesai,status_akun FROM akun WHERE id_akun=? AND role='fo'");$s->bind_param('i',$id);$s->execute();$row=api_one($s);$s->close();if(!$row)throw new OutOfBoundsException('Akun FO tidak ditemukan.');api_reply(200,true,'Biodata FO berhasil diambil.',$row);}
$b=api_body();$changes=$b['perubahan']??[];if(!is_array($changes)||!$changes)throw new InvalidArgumentException('perubahan harus berisi minimal satu data yang diajukan.');$allowed=['nama','no_telp','alamat','gender','jam_mulai','jam_selesai'];foreach($changes as $key=>$value)if(!in_array($key,$allowed,true))throw new InvalidArgumentException('Field perubahan tidak diizinkan: '.$key);$s=$conn->prepare("SELECT nama,no_telp,alamat,gender,jam_mulai,jam_selesai FROM akun WHERE id_akun=? AND role='fo'");$s->bind_param('i',$id);$s->execute();$old=api_one($s);$s->close();if(!$old)throw new OutOfBoundsException('Akun FO tidak ditemukan.');$conn->begin_transaction();try{$insert=$conn->prepare("INSERT INTO pengajuan_perubahan(id_akun,field_diajukan,nilai_lama,nilai_baru,alasan,status,status_pengajuan) VALUES(?,?,?,?,?,'proses','menunggu')");$reason=api_string($b['alasan']??'', 'alasan',1000,false)??'';foreach($changes as $field=>$value){if($field==='gender'&&!in_array($value,['L','P'],true))throw new InvalidArgumentException('gender harus L atau P.');$newValue=api_string($value,$field,1000);$oldValue=(string)($old[$field]??'');$insert->bind_param('issss',$id,$field,$oldValue,$newValue,$reason);$insert->execute();}$insert->close();$conn->commit();}catch(Throwable $e){$conn->rollback();throw $e;}api_reply(201,true,'Pengajuan perubahan berhasil dikirim dan menunggu persetujuan Admin.',['id_akun'=>$id,'jumlah_pengajuan'=>count($changes)]);
}catch(Throwable $e){api_db_error($e);}